async (state) => {
  const fs = require('fs');
  const lines = [];
  if (state.sprintContract) {
    lines.push('=== 実装対象のContext ===');
    lines.push('Goals: ' + state.sprintContract.goals.join(', '));
    lines.push('Sprint: ' + state.sprintContract.sprintNumber);
  }
  lines.push('\n=== 既存テストファイル ===');
  try {
    const { execSync } = require('child_process');
    const patterns = ['*.test.*', '*_test.*', '*_spec.*', '*.spec.*', '*Test.*', '*.test.go', '*.test.py', '*.test.ts', '*.test.js'];
    const foundTests = [];
    for (const p of patterns) {
      try {
        const tests = execSync('find . -name "' + p + '" -not -path "*/node_modules/*" -not -path "*/vendor/*" | head -10', { encoding: 'utf8' });
        const found = tests.trim();
        if (found) {
          const files = found.split('\n').slice(0, 5).join(', ');
          foundTests.push('[' + p + '] ' + files);
        }
      } catch (e) {}
    }
    lines.push(foundTests.length > 0 ? foundTests.join('\n') : 'なし');
  } catch (e) {
    lines.push('（取得失敗）');
  }
  if (state.sprintResult && !state.sprintResult.passed) {
    lines.push('\n=== 前回フィードバック ===');
    lines.push(state.sprintResult.feedback);
  }
  const { HumanMessage } = require('@langchain/core/messages');
  return { activeMessages: [new HumanMessage('=== Generator Bootstrap ===\n' + lines.join('\n'))] };
}

async (state) => {
  const LIMIT = 200000;
  const THRESHOLD = LIMIT * 0.70;
  const tokens = ((state.messages || []).concat(state.activeMessages || [])).reduce((sum, msg) => {
    const c = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);
    return sum + Math.ceil(c.length / 4);
  }, 0);
  if (tokens < THRESHOLD) {
    return { estimatedContextTokens: tokens };
  }
  console.warn(
    '[ContextGuard] Estimated tokens: ' + tokens + ' exceeds threshold: ' + THRESHOLD +
    '. Performing context reset. (Reset count: ' + ((state.contextResetCount ?? 0) + 1) + ')'
  );
  const parts = [
    '=== Context Reset: 重要な状態の引き継ぎ ===',
    state.taskSpec ? 'タスク仕様: ' + state.taskSpec : null,
    state.sprintContract ? '現在のSprintContract: ' + JSON.stringify(state.sprintContract, null, 2) : null,
    state.sprintResult ? '前回の評価結果: ' + JSON.stringify(state.sprintResult, null, 2) : null,
    'リトライ回数: ' + (state.retryCount ?? 0),
    '=== 以上を引き継いで作業を継続してください ==='
  ].filter(Boolean).join('\n');
  return {
    activeMessages: [new HumanMessage(parts)],
    messages: [],
    estimatedContextTokens: Math.ceil(parts.length / 4),
    contextResetCount: (state.contextResetCount ?? 0) + 1,
    lastContextResetAt: new Date().toISOString()
  };
}

async (state) => {
  const fs = require('fs');
  const lines = [];
  lines.push('=== 起動・テストコマンド ===');
  const configFiles = [
    { name: 'package.json', patterns: ['start', 'dev', 'serve', 'build', 'test'] },
    { name: 'Makefile', patterns: ['all', 'build', 'test', 'run', 'start', 'dev'] },
    { name: 'Rakefile', patterns: ['build', 'test', 'run'] },
    { name: 'Cargo.toml', patterns: ['build', 'test', 'run'] },
  ];
  const foundScripts = [];
  for (const cfg of configFiles) {
    try {
      const content = fs.readFileSync(cfg.name, 'utf8');
      if (cfg.name === 'package.json') {
        const pkg = JSON.parse(content);
        const scripts = pkg.scripts || {};
        const found = cfg.patterns.filter(p => scripts[p]).map(p => p + ': ' + scripts[p]);
        if (found.length > 0) foundScripts.push('--- ' + cfg.name + ' ---\n' + found.join('\n'));
      } else if (cfg.name === 'Makefile') {
        const targets = cfg.patterns.filter(p => content.includes(p + ':'));
        if (targets.length > 0) foundScripts.push('--- ' + cfg.name + ' ---\n' + targets.join(', ') + ' ターゲットあり');
      } else {
        const targets = cfg.patterns.filter(p => content.includes(p));
        if (targets.length > 0) foundScripts.push('--- ' + cfg.name + ' ---\n' + targets.join(', ') + ' あり');
      }
    } catch (e) {}
  }
  if (foundScripts.length > 0) {
    lines.push(foundScripts.join('\n'));
  } else {
    lines.push('設定ファイルなし');
  }
  lines.push('\n=== APIエンドポイント ===');
  try {
    const { execSync } = require('child_process');
    const p = 'grep -rn "\\.\\(get\\|post\\|put\\|delete\\|patch\\)" --include="*.ts" --include="*.js" --include="*.py" --include="*.go" --include="*.rb" --include="*.java" | grep -E "(app|router|@|route|Handle|Controller)" | head -30';
    const ep = execSync(p, { encoding: 'utf8' });
    lines.push(ep.trim() || 'なし');
  } catch (e) {
    lines.push('（取得失敗）');
  }
  if (state.sprintContract) {
    lines.push('\n=== 評価基準 ===');
    state.sprintContract.successCriteria.forEach((c, i) => lines.push((i + 1) + '. ' + c));
  }
  const { HumanMessage } = require('@langchain/core/messages');
  return { activeMessages: [new HumanMessage('=== Evaluator Bootstrap ===\n' + lines.join('\n'))] };
}

async (state) => {
  const { execSync } = require('child_process');
  const lines = [];
  if (state.sprintResult) {
    lines.push('=== 評価フィードバック ===');
    lines.push('スコア: ' + state.sprintResult.score);
    lines.push('フィードバック: ' + state.sprintResult.feedback);
  }
  lines.push('\n=== 直近の変更ファイル ===');
  try {
    const diff = execSync('git diff --stat HEAD 2>/dev/null | head -20', { encoding: 'utf8' });
    lines.push(diff.trim() || '変更なし');
  } catch (e) {
    lines.push('（取得失敗）');
  }
  lines.push('\n=== ビルドエラー（直近） ===');
  const buildCommands = [
    'yarn build 2>&1 | tail -20',
    'npm run build 2>&1 | tail -20',
    'make build 2>&1 | tail -20',
    'cargo build 2>&1 | tail -20',
    'go build ./... 2>&1 | tail -20',
    'python -m py_compile setup.py 2>&1 | tail -20',
    'bundle exec rake build 2>&1 | tail -20',
  ];
  let buildOutput = '（ビルドコマンドなし）';
  for (const cmd of buildCommands) {
    try {
      buildOutput = execSync(cmd, { encoding: 'utf8' });
      if (buildOutput.trim()) break;
    } catch (e) {}
  }
  lines.push(buildOutput.trim() || '（取得失敗）');
  const { HumanMessage } = require('@langchain/core/messages');
  const num = state.sprintContract ? state.sprintContract.sprintNumber : '?';
  return { activeMessages: [new HumanMessage('=== Feedback Bootstrap（スプリント' + num + '） ===\n' + lines.join('\n'))] };
}

async (state) => {
  const MAX_RETRIES = 3;
  if (!state.sprintResult) {
    return 'generator_node';
  }
  if (state.sprintResult.passed) {
    return '__end__';
  }
  if (state.retryCount >= MAX_RETRIES) {
    console.warn(`Sprint Contract: MAX_RETRIES(${MAX_RETRIES})に到達。強制終了します。`);
    return '__end__';
  }
  return 'bootstrap_feedback_node';
}
